<?php
require_once __DIR__.'/bootstrap/app.php';require_login();$u=current_user();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($action==='read'){db_execute('UPDATE NOTIFICATION_RECIPIENT SET ReadAt=NOW() WHERE NotificationID=? AND UserID=?','ii',[(int)$_POST['notification_id'],$u['UserID']]);}elseif($action==='send'){require_role('SUPER_ADMIN','TRAINER');$title=trim($_POST['title']??'');$body=trim($_POST['body']??'');$aud=$_POST['audience']??'';if($title===''||$body==='')throw new RuntimeException('Title and message are required.');if(is_role('SUPER_ADMIN')){$allowed=['MEMBER','TRAINER','RECEPTIONIST','ALL'];if(!in_array($aud,$allowed,true))throw new RuntimeException('Invalid audience.');$ids=$aud==='ALL'?array_column(db_all("SELECT UserID FROM USER_ACCOUNT WHERE Status='ACTIVE'"),'UserID'):array_column(db_all("SELECT UserID FROM USER_ACCOUNT WHERE Role=? AND Status='ACTIVE'",'s',[$aud]),'UserID');}else{$classId=(int)($_POST['class_id']??0);$owned=db_one('SELECT ClassID FROM CLASS WHERE ClassID=? AND TrainerID=?','ii',[$classId,$u['TrainerID']]);if(!$owned)throw new RuntimeException('Choose one of your classes.');$ids=array_column(db_all("SELECT ua.UserID FROM ENROLLMENT e JOIN USER_ACCOUNT ua ON ua.MemberID=e.MemberID WHERE e.ClassID=? AND e.Status='ENROLLED'",'i',[$classId]),'UserID');}notify_users($ids,$title,$body,'ANNOUNCEMENT');audit('notification.broadcast','NOTIFICATION',null,['audience'=>$aud,'recipients'=>count($ids)]);set_flash('success','Notification sent to '.count($ids).' recipient(s).');}redirect('notifications.php');}catch(Throwable $e){$errors[]=$e->getMessage();}}
$rows=db_all('SELECT n.*,r.ReadAt,u.Email SenderEmail FROM NOTIFICATION_RECIPIENT r JOIN NOTIFICATION n ON n.NotificationID=r.NotificationID LEFT JOIN USER_ACCOUNT u ON u.UserID=n.SenderUserID WHERE r.UserID=? ORDER BY n.CreatedAt DESC LIMIT 100','i',[$u['UserID']]);$classes=is_role('TRAINER')?db_all("SELECT ClassID,ClassName FROM CLASS WHERE TrainerID=? AND Status='SCHEDULED'",'i',[$u['TrainerID']]):[];$pageTitle='Notifications';$pageSubtitle='Announcements and account updates';include ROOT_PATH.'/includes/header.php';?>
<?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><?php if(is_role('SUPER_ADMIN','TRAINER')):?><div class="form-card notification-compose"><h2 class="section-title">Send notification</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="send"><div class="form-grid"><div class="form-group"><label for="title">Title</label><input id="title" name="title" maxlength="150" required></div><div class="form-group"><label for="audience"><?=is_role('TRAINER')?'Class':'Audience'?></label><?php if(is_role('TRAINER')):?><select id="audience" name="class_id" required><option value="">Choose your class</option><?php foreach($classes as $c):?><option value="<?=$c['ClassID']?>"><?=e($c['ClassName'])?></option><?php endforeach;?></select><?php else:?><select id="audience" name="audience" required><option value="MEMBER">All active members</option><option value="TRAINER">All active trainers</option><option value="RECEPTIONIST">Receptionists</option><option value="ALL">Everyone</option></select><?php endif;?></div><div class="form-group form-full"><label for="body">Message</label><textarea id="body" name="body" required></textarea></div></div><div class="form-actions"><button class="btn btn-primary">Send notification</button></div></form></div><?php endif;?>
<div class="notification-list"><?php foreach($rows as $r):?><article class="notification-item <?=$r['ReadAt']?'':'unread'?>"><div><span class="badge badge-blue"><?=e($r['Type'])?></span><h2><?=e($r['Title'])?></h2><p><?=nl2br(e($r['Body']))?></p><small><?=e(date('d M Y H:i',strtotime($r['CreatedAt'])))?><?= $r['SenderEmail']?' · '.e($r['SenderEmail']):''?></small><?php if($r['EntityType']==='CONVERSATION'&&$r['EntityID']):?><div class="form-actions"><a class="btn btn-ghost btn-sm" href="<?=e(base_url('messages.php?conversation_id='.(int)$r['EntityID']))?>">Open conversation</a></div><?php endif;?></div><?php if(!$r['ReadAt']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="read"><input type="hidden" name="notification_id" value="<?=$r['NotificationID']?>"><button class="btn btn-ghost btn-sm">Mark read</button></form><?php endif;?></article><?php endforeach;if(!$rows):?><div class="empty-state">No notifications yet.</div><?php endif;?></div><?php include ROOT_PATH.'/includes/footer.php';?>
